const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const tokens=v=>norm(v).split(/[^a-z0-9]+/).filter(Boolean);
export function buildSearchIndex(documents=[],{fields=['name','title','description'],weights={}}={}){const docs=documents.map((doc,position)=>{const fieldTokens={};for(const field of fields)fieldTokens[field]=tokens(doc?.[field]);return Object.freeze({id:String(doc.id??position),position,doc,fieldTokens})});return Object.freeze({fields:Object.freeze([...fields]),weights:Object.freeze({...weights}),documents:Object.freeze(docs)})}
export function searchIndex(index,query,{limit=20,filter=null}={}){const q=tokens(query);if(!q.length)return[];return index.documents.filter(x=>!filter||filter(x.doc)).map(x=>{let score=0;for(const field of index.fields){const weight=Number(index.weights[field]??1);for(const term of q)if(x.fieldTokens[field].some(t=>t===term||t.startsWith(term)))score+=weight}return{x,score}}).filter(r=>r.score>0).sort((a,b)=>b.score-a.score||a.x.position-b.x.position).slice(0,limit).map(r=>Object.freeze({id:r.x.id,score:r.score,document:r.x.doc}))}
